use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything outside the RFC 3986 unreserved set, so the
/// input text cannot alter the URL's host, path, or query structure.
fn percent_encode(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for &b in text.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// Convert Unix seconds (UTC) to a `YYYY-MM-DD` string.
/// Uses Howard Hinnant's civil-from-days algorithm.
fn utc_date(seconds: u64) -> String {
    let days = (seconds / 86_400) as i64;
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    if month <= 2 {
        year += 1;
    }
    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Read the clock first so `started` is as close to the start of the run as possible.
        let now = wall_clock::now();

        // Enrichment fetch: fire-and-forget. Its result must not change this
        // node's output, so it is deliberately discarded. A transport failure
        // is returned as a value and ignored; an out-of-allowlist request traps
        // at the boundary as specified by the interface.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&tick.reason));
        let _ = http_client::fetch(&url);

        RunInfo {
            date: utc_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
